      "path": "ChatMachines/GeminiSupervisor/scripts/sync-stable-readers.js",
      "purpose": "Deterministic stable-reader builder maintaining ordered JSON projections directly derived from authoritative canonical documents.",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const rootDir = path.resolve(__dirname, '../../..');
const depMapPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/dependency-map.json');

function computeHash(content) {
  return crypto.createHash('sha256').update(content, 'utf8').digest('hex');
}

function parseMarkdownToItems(text) {
  const normalized = text.replace(/\r\n/g, '\n');
  const paragraphs = normalized.split(/\n\n+/);
  const items = [];
  let currentHeading = null;

  paragraphs.forEach((chunk) => {
    const trimmed = chunk.trim();
    if (!trimmed) return;
    const headingMatch = trimmed.match(/^(#{1,6})\s+(.+)$/m);
    if (headingMatch && trimmed.startsWith(headingMatch[0])) {
      currentHeading = headingMatch[2].trim();
    }
    items.push({
      type: 'content',
      index: items.length,
      topic: currentHeading,
      text: trimmed
    });
  });

  return items;
}

function parseJsonToItems(text) {
  const parsed = JSON.parse(text);
  const items = [];

  if (Array.isArray(parsed)) {
    parsed.forEach((val, idx) => {
      items.push({
        type: 'content',
        index: items.length,
        key_path: `[${idx}]`,
        value: val
      });
    });
  } else if (typeof parsed === 'object' && parsed !== null) {
    Object.keys(parsed).forEach((k) => {
      items.push({
        type: 'content',
        index: items.length,
        key_path: k,
        value: parsed[k]
      });
    });
  } else {
    items.push({
      type: 'content',
      index: 0,
      key_path: '$',
      value: parsed
    });
  }

  return items;
}

function syncAllStableReaders() {
  const depMap = JSON.parse(fs.readFileSync(depMapPath, 'utf8'));
  const registry = depMap.truth_readable_registry;
  let changedCount = 0;

  for (const [docId, meta] of Object.entries(registry)) {
    const canonicalAbs = path.join(rootDir, meta.canonical_path);
    const readerAbs = path.join(rootDir, meta.stable_reader_path);

    if (!fs.existsSync(canonicalAbs)) {
      console.warn(`[sync-stable-readers] Canonical file missing: ${meta.canonical_path}`);
      continue;
    }

    const rawContent = fs.readFileSync(canonicalAbs, 'utf8');
    const rawHash = computeHash(rawContent);
    let existingReader = null;

    if (fs.existsSync(readerAbs)) {
      try {
        existingReader = JSON.parse(fs.readFileSync(readerAbs, 'utf8'));
      } catch (e) {
        existingReader = null;
      }
    }

    if (existingReader && existingReader.provenance && existingReader.provenance.source_sha256 === rawHash) {
      continue;
    }

    const items = meta.format === 'json' ? parseJsonToItems(rawContent) : parseMarkdownToItems(rawContent);

    const readerPayload = {
      doc_id: docId,
      canonical_path: meta.canonical_path,
      format: meta.format,
      provenance: {
        source_sha256: rawHash,
        synced_at: new Date().toISOString()
      },
      item_count: items.length,
      items
    };

    fs.mkdirSync(path.dirname(readerAbs), { recursive: true });
    fs.writeFileSync(readerAbs, JSON.stringify(readerPayload, null, 2) + '\n', 'utf8');
    changedCount++;
    console.log(`[sync-stable-readers] Updated stable reader for ${docId} -> ${meta.stable_reader_path}`);
  }

  const sentinelPath = path.join(rootDir, depMap.sentinel_file);
  fs.mkdirSync(path.dirname(sentinelPath), { recursive: true });
  fs.writeFileSync(sentinelPath, `synced_at=${new Date().toISOString()}\nchanged_readers=${changedCount}\n`, 'utf8');
  return changedCount;
}

if (require.main === module) {
  syncAllStableReaders();
}

module.exports = { syncAllStableReaders };
