      "purpose": "Deterministic engine for CSPRNG seed injection into active projections, snapshot management, and in-place swap verification.",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const rootDir = path.resolve(__dirname, '../../..');
const catalogPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/truth-catalog.json');
const selectorPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/truth-selector.json');
const statusPath = path.join(rootDir, 'ChatMachines/GeminiSupervisor/truth-status.json');
const snapshotsDir = path.join(rootDir, 'ChatMachines/GeminiSupervisor/.truth-snapshots');

function getCatalog() {
  return JSON.parse(fs.readFileSync(catalogPath, 'utf8')).catalog;
}

function generateRandomHex(byteCount = 16) {
  return crypto.randomBytes(byteCount).toString('hex');
}

function createSeedItem(index, seedId) {
  const seedValue = generateRandomHex(16);
  const proofValue = '0'.repeat(seedValue.length);
  return {
    type: 'truth_seed',
    seed_id: seedId,
    index,
    seed_value: seedValue,
    proof_value: proofValue
  };
}

function injectSeedsIntoReader(readerData, challengeId) {
  const originalItems = readerData.items;
  const totalItems = originalItems.length;
  const seededItems = [];

  const seedInterval = Math.max(2, Math.min(5, Math.floor(totalItems / 4) || 2));
  let seedIndex = 0;

  originalItems.forEach((item, idx) => {
    seededItems.push(item);
    if ((idx + 1) % seedInterval === 0 || idx === totalItems - 1) {
      const seedId = `${readerData.doc_id}-seed-${seedIndex++}`;
      seededItems.push(createSeedItem(seededItems.length, seedId));
    }
  });

  return {
    challenge_id: challengeId,
    doc_id: readerData.doc_id,
    canonical_path: readerData.canonical_path,
    provenance: readerData.provenance,
    total_items: seededItems.length,
    items: seededItems
  };
}

function generateChallenge() {
  const selector = JSON.parse(fs.readFileSync(selectorPath, 'utf8'));
  const catalog = getCatalog();
  const selectedDocs = Object.keys(selector.selected_documents || {}).filter(
    (docId) => selector.selected_documents[docId] === true
  );

  if (selectedDocs.length === 0) {
    console.log('[truth-challenge-engine] No documents selected. Nothing to generate.');
    return { generated: false, reason: 'none_selected' };
  }

  const challengeId = 'tc-' + Date.now() + '-' + generateRandomHex(4);
  fs.mkdirSync(snapshotsDir, { recursive: true });

  const activeFiles = [];

  for (const docId of selectedDocs) {
    const entry = catalog.find((c) => c.id === docId);
    if (!entry) {
      throw new Error(`Document ID '${docId}' not found in catalog.`);
    }
    const stableReaderAbs = path.join(rootDir, entry.stable_reader_path);
    if (!fs.existsSync(stableReaderAbs)) {
      throw new Error(`Stable reader missing at ${entry.stable_reader_path}. Run sync first.`);
    }
    const readerData = JSON.parse(fs.readFileSync(stableReaderAbs, 'utf8'));
    const projection = injectSeedsIntoReader(readerData, challengeId);

    const activeAbs = path.join(rootDir, entry.active_projection_path);
    const snapshotAbs = path.join(snapshotsDir, `${docId}.snapshot.json`);

    fs.mkdirSync(path.dirname(activeAbs), { recursive: true });
    const serialized = JSON.stringify(projection, null, 2) + '\n';
    fs.writeFileSync(activeAbs, serialized, 'utf8');
    fs.writeFileSync(snapshotAbs, serialized, 'utf8');
    activeFiles.push(entry.active_projection_path);
  }

  const newStatus = {
    challenge_id: challengeId,
    status: 'ACTIVE',
    timestamp: new Date().toISOString(),
    selected: selectedDocs,
    active_files: activeFiles,
    summary: 'Active seeded projections ready for worker reading and in-place seed swapping.'
  };
  fs.writeFileSync(statusPath, JSON.stringify(newStatus, null, 2) + '\n', 'utf8');
  console.log(`[truth-challenge-engine] Challenge generated successfully: ${challengeId}`);
  return { generated: true, challengeId };
}

function verifyChallenge() {
  if (!fs.existsSync(statusPath)) {
    console.log('[truth-challenge-engine] Status file does not exist. Skipping verification.');
    return { verified: false, action: 'noop' };
  }

  const currentStatus = JSON.parse(fs.readFileSync(statusPath, 'utf8'));
  if (currentStatus.status !== 'ACTIVE') {
    console.log(`[truth-challenge-engine] Current status is '${currentStatus.status}'. No active challenge to verify.`);
    return { verified: false, action: 'noop' };
  }

  const catalog = getCatalog();
  const selectedDocs = currentStatus.selected || [];
  let allPassed = true;
  const failureReasons = [];

  for (const docId of selectedDocs) {
    const entry = catalog.find((c) => c.id === docId);
    const snapshotAbs = path.join(snapshotsDir, `${docId}.snapshot.json`);
    const activeAbs = path.join(rootDir, entry.active_projection_path);

    if (!fs.existsSync(snapshotAbs)) {
      failureReasons.push(`Snapshot missing for ${docId}`);
      allPassed = false;
      break;
    }
    if (!fs.existsSync(activeAbs)) {
      failureReasons.push(`Active projection missing for ${docId}`);
      allPassed = false;
      break;
    }

    const originalSnapshot = JSON.parse(fs.readFileSync(snapshotAbs, 'utf8'));
    let workerProjection;
    try {
      workerProjection = JSON.parse(fs.readFileSync(activeAbs, 'utf8'));
    } catch (err) {
      failureReasons.push(`Active projection for ${docId} is invalid JSON: ${err.message}`);
      allPassed = false;
      break;
    }

    if (originalSnapshot.challenge_id !== workerProjection.challenge_id ||
        originalSnapshot.doc_id !== workerProjection.doc_id ||
        originalSnapshot.canonical_path !== workerProjection.canonical_path ||
        originalSnapshot.items.length !== workerProjection.items.length) {
      failureReasons.push(`Structural mismatch or element count altered in ${docId}`);
      allPassed = false;
      break;
    }

    for (let i = 0; i < originalSnapshot.items.length; i++) {
      const orig = originalSnapshot.items[i];
      const work = workerProjection.items[i];

      if (orig.type === 'truth_seed') {
        if (work.type !== 'truth_seed' ||
            work.seed_id !== orig.seed_id ||
            work.index !== orig.index) {
          failureReasons.push(`Seed metadata mutated at index ${i} in ${docId}`);
          allPassed = false;
          break;
        }
        if (work.seed_value !== orig.proof_value || work.proof_value !== orig.seed_value) {
          failureReasons.push(`Seed swap condition failed at seed_id ${orig.seed_id} in ${docId}`);
          allPassed = false;
          break;
        }
      } else {
        if (JSON.stringify(orig) !== JSON.stringify(work)) {
          failureReasons.push(`Content element mutated at index ${i} in ${docId}`);
          allPassed = false;
          break;
        }
      }
    }

    if (!allPassed) break;
  }

  if (allPassed) {
    console.log('[truth-challenge-engine] Verification PASSED. Executing atomic cleanup.');
    const selector = JSON.parse(fs.readFileSync(selectorPath, 'utf8'));
    for (const key of Object.keys(selector.selected_documents)) {
      selector.selected_documents[key] = false;
    }
    fs.writeFileSync(selectorPath, JSON.stringify(selector, null, 2) + '\n', 'utf8');

    for (const docId of selectedDocs) {
      const entry = catalog.find((c) => c.id === docId);
      const activeAbs = path.join(rootDir, entry.active_projection_path);
      const snapshotAbs = path.join(snapshotsDir, `${docId}.snapshot.json`);
      if (fs.existsSync(activeAbs)) fs.unlinkSync(activeAbs);
      if (fs.existsSync(snapshotAbs)) fs.unlinkSync(snapshotAbs);
    }

    const passStatus = {
      challenge_id: currentStatus.challenge_id,
      status: 'PASS',
      timestamp: new Date().toISOString(),
      selected: selectedDocs,
      summary: 'All truth seeds swapped correctly in-place. Challenge verified.'
    };
    fs.writeFileSync(statusPath, JSON.stringify(passStatus, null, 2) + '\n', 'utf8');
    return { verified: true, action: 'pass_cleanup' };
  } else {
    console.warn(`[truth-challenge-engine] Verification FAILED. Reasons: ${failureReasons.join('; ')}`);
    console.warn('[truth-challenge-engine] Restoring original seeded snapshots for retry.');
    for (const docId of selectedDocs) {
      const entry = catalog.find((c) => c.id === docId);
      const snapshotAbs = path.join(snapshotsDir, `${docId}.snapshot.json`);
      const activeAbs = path.join(rootDir, entry.active_projection_path);
      if (fs.existsSync(snapshotAbs)) {
        fs.copyFileSync(snapshotAbs, activeAbs);
      }
    }
    return { verified: false, action: 'restored_snapshot', reasons: failureReasons };
  }
}

const command = process.argv[2];
if (command === 'generate') {
  generateChallenge();
} else if (command === 'verify') {
  verifyChallenge();
} else {
  module.exports = { generateChallenge, verifyChallenge };
}
